from common_e14 import *
import numpy as np
from scipy.spatial import cKDTree
def main():
 verify_protocol();assert read(R/'00_integrity/G2_G3_G4_CONTEXT_PASS.json')['passed'];checks=[]
 for a in rows(R/'OBSERVATION_WINDOW_COORDINATES.csv'):
  g=dict(np.load(a['geometry_path']));assert sha(a['geometry_path'])==a['geometry_SHA256'];x=g['xyz'];t=g['triangles'];n=len(x);cross=np.cross(x[t[:,1]]-x[t[:,0]],x[t[:,2]]-x[t[:,0]]);ta=np.linalg.norm(cross,axis=1)/2;area=np.bincount(t.ravel(),weights=np.repeat(ta/3,3),minlength=n);normal=np.stack([np.bincount(t.ravel(),weights=np.repeat(cross[:,j]/2,3),minlength=n) for j in range(3)],1);normal/=np.linalg.norm(normal,axis=1)[:,None];center=(x*area[:,None]).sum(0)/area.sum();order=np.lexsort((x[:,2],x[:,1],x[:,0]));q=np.linspace(0,n-1,128,dtype=int);tree=cKDTree(x[order]);nb=order[tree.query(x[q],k=16,workers=2)[1]];dims=np.ptp(x,axis=0)/60;features=np.c_[(x[q]-center)/60,normal[q],np.tile(dims,(len(q),1)),np.tile([1.,0,0],(len(q),1)),np.zeros(len(q)),x[q,2]-x[nb,2].mean(1),np.linalg.norm(normal[q]-normal[nb].mean(1),axis=1),np.log1p(area[q]),np.tile([normal[:,0].std(),normal[:,1].std(),np.ptp(x[:,2])/60],(len(q),1))].astype('f4');error=float(np.max(abs(features-g['features'][q])));assert error<=2e-6;assert np.max(abs(area-g['area']))<1e-12;assert np.max(abs(normal-g['normal']))<1e-12
  full=dict(np.load(H/'02_geometry'/(a['source_id']+'.npz')));assert np.array_equal(x,full['xyz'][g['source_ids']]);assert x[:,0].min()>=float(a['declared_X_min'])-1e-8 and x[:,0].max()<=float(a['declared_X_max'])+1e-8;assert len(set(g['source_ids'][g['context']]))==4096
  support=dict(np.load(R/'03_source_geometry'/(a['source_id']+'_SUPPORT.npz')));qq=np.flatnonzero(support['core']&(support['tile_id']==int(a['tile'])));mapped=np.searchsorted(g['source_ids'],qq);assert np.array_equal(g['source_ids'][mapped],qq);k16=np.linalg.norm(x[g['neighbors'][mapped]]-x[mapped,None,:],axis=2);checks.append(dict(source_id=a['source_id'],condition=a['condition'],tile=a['tile'],channel_max_abs_error=error,visible_context_points=4096,visible_vertices=n,query_points=len(qq),minimum_query_X_edge_mm=float(np.minimum(x[mapped,0]-x[:,0].min(),x[:,0].max()-x[mapped,0]).min()),minimum_query_Y_edge_mm=float(np.minimum(x[mapped,1]-x[:,1].min(),x[:,1].max()-x[mapped,1]).min()),maximum_K16_radius_mm=float(k16.max()),input_window_area_recomputed=True,original_target_T0_unchanged=True,all_features_visible_only=True,passed=True))
  print('VISIBILITY_AUDITED',a['source_id'],a['condition'],a['tile'],flush=True)
 table(R/'17_independent_audits/FEATURE_VISIBILITY_CHECKS.csv',checks);write(R/'17_independent_audits/FEATURE_VISIBILITY_PASS.json',dict(UTC=now(),passed=True,windows=len(checks),separate_bincount_feature_reconstruction=True,features_checked_per_window=128,channels=19,maximum_error=max(a['channel_max_abs_error'] for a in checks)))
if __name__=='__main__':main()
